//MilkDrop (HLSL) Port by Incubo_
//TODO: Make these carts not jittery.
//BEGIN//
vec2 R;
#define st(a, b, t) smoothstep(a, b, t)
vec2 rot(vec2 p, float a){
return vec2(p.x*cos(a) - p.y*sin(a), p.x*sin(a) + p.y*cos(a));
}
float height(float x){
return sin(x*2.)*.15 + sin(x*3.)*.13 + sin(x*6.)*.02;
}
float aDx(float x){
float h = .001;
float y = height(x+h) - height(x);
return atan(y, h);
}
float box(vec2 uv1, vec2 dim, float b)
{
uv1 = abs(uv1);
float bx = st(b, -b, uv1.y - dim.y);
bx *= st(b, -b, uv1.x - dim.x );
return bx;
}
float circle(vec2 uv2, float r, float b){
return st(r + b, r - b, length(uv2));
}
float rtr(vec2 uv3, vec2 scale, float h,  float b){
uv3.y -= h;
uv3 *= scale;
float tri = st(b, -b, dot(uv3, vec2(1., 1.)));
tri *= st(-b, b, uv3.y + h);
tri *= st(-b, b, uv3.x);
return tri;
}
vec4 track(vec2 uv4){
float b = .01;
float trk = .0;
float sup = .0;
trk += st(-.005, .005, uv4.y + height(uv4.x) + .007);
trk *= st(.005, -.005, uv4.y + height(uv4.x) - .007);
vec2 ruv = fract(uv4*8.) - .5;
sup += st(.08, .07, abs(dot(ruv, vec2(1., 1.))));
sup += st(.08, .07, abs(dot(ruv, vec2(-1., 1.))));
sup *= st(.001, -.001, uv4.y + height(uv4.x)+.007);
vec3 col = vec3(.7, .7, .7)*trk;
return vec4(col, trk + sup);
}
vec4 car(vec2 uv5){
float b = .02;
vec3 col = vec3( 0.0 , 0.0 , 0.0 );
float a = 0.;
float wheel = 0.;
a += box(uv5, vec2(.7, .1), b);
a += box(uv5, vec2(0.75, .06), b);
a += box(uv5 - vec2(0., .2), vec2(.5, .1), b);
a += box(uv5 - vec2(0., -.2), vec2(.5, .1), b);
a += rtr(vec2(-uv5.x, uv5.y)-vec2(.5, .1), vec2(1., 1.), .2, b);
a += rtr(vec2(-uv5.x, -uv5.y)-vec2(.5, .1), vec2(1., 1.), .2, b);
a += rtr(vec2(uv5.x, uv5.y)-vec2(.5, .1), vec2(1., 1.), .2, b);
a += rtr(vec2(uv5.x, -uv5.y)-vec2(.5, .1), vec2(1., 1.), .2, b);
a -= box(uv5-vec2(-.25, .2), vec2(.15, .1), b);
a -= box(uv5-vec2(.25, .2), vec2(.15, .1), b);
a = clamp(a, 0., 1.);
wheel += circle(uv5-vec2(.4,-.35), .15, .01);
wheel += circle(uv5-vec2(-.4,-.35), .15, .01);
col = a * mix(vec3(.8, 0., 0.),vec3(.8, .8, 0.),
st(.2, .06, abs(uv5.y+.2)));
col *= st(.01, .4, abs(uv5.y+.44));
col *= st(.0, .2, abs(uv5.y-.38));
col *= st(.0, .9, abs(uv5.x+1.15));
col *= 1.-wheel;
return vec4(col, a + wheel);
}
vec4 hill(vec2 uv6){
float a = st(0.015, -0.015, uv6.y - height(uv6.x));
vec3 col = vec3( 0.0 , 0.0 , 0.0 );
col += max(uv6.y+1.075, .1)*vec3(0.1, 0.43, 0.2) * a;
return vec4(col, a);
}
